-- Real photo support for real model_profiles rows — the mock roster
-- (SAMPLE_TALENT) has had photo:string since earlier this session, but
-- real models (Supabase-backed, e.g. Nora Kim) had no photo field at
-- all. Stored as a data URI directly in the column rather than standing
-- up Supabase Storage for what's currently a handful of demo/seed
-- photos — revisit with real object storage once models are actually
-- uploading their own.
alter table model_profiles add column photo_url text;

update model_profiles
set photo_url = 'data:image/jpeg;base64,'
where id = 'd00f981f-d607-4e1d-b7b7-27157500cd2e'; -- Nora Kim
